const ID_SPOKEN_UNITS = [
    [/µm\b|μm\b/g, ' mikrometer'], [/µS\b|μS\b/g, ' mikrosiemens'], [/µg\/dL/g, ' mikrogram per desiliter'],
    [/µg\/m³/g, ' mikrogram per meter kubik'], [/mmHg\b/g, ' milimeter merkuri'], [/mGy-Eq\b/g, ' miligrei ekuivalen'],
    [/mGy\/(hr|d)\b/g, ' miligrei per hari'], [/mGy\b/g, ' miligrei'], [/mg\/(hari|hr|d)\b/g, ' miligram per hari'],
    [/mg\/L\b/g, ' miligram per liter'], [/mm²/g, ' milimeter persegi'], [/dBA\b/g, ' desibel A'], [/dB\b/g, ' desibel'],
    [/(\d)\s*ms\b/g, '$1 milidetik'], [/\bbpm\b/g, ' denyut per menit'], [/\bWPM\b/g, ' kata per menit'],
    [/\bppm\b/g, ' pe pe em'], [/\bHz\b/g, ' hertz'], [/°C\b/g, ' derajat Celsius'], [/°/g, ' derajat'],
    [/(\d)\s*%/g, '$1 persen'], [/\bmnt\b/g, ' menit'], [/\bthn\b/gi, ' tahun'], [/(\d)\s*x\b/g, '$1 kali'],
    [/peaks\/mnt/g, 'puncak per menit'], [/\/mnt\b/g, ' per menit'], [/\/hari\b/g, ' per hari']
];
function toIndonesianSpeech(text) {
    let t = ` ${text || ''} `;
    t = t
        .replace(/\bDr\.\s*/g, 'Dokter ').replace(/\bCmdr\.\s*/g, 'Komandan ').replace(/\bSpec\.\s*/g, 'Spesialis ')
        .replace(/\bLt\.\s*/g, 'Letnan ').replace(/\bCapt\.\s*/g, 'Kapten ').replace(/\bEng\.\s*/g, 'Insinyur ')
        .replace(/\bD\s*\+\s*(\d+)/g, 'hari ke $1').replace(/\bhari hari ke\b/gi, 'hari ke')
        .replace(/\b(astronot\s+)?AST-0*(\d+)/gi, 'astronot nomor $2').replace(/\b(misi\s+)?INC-0*(\d+)/gi, 'misi nomor $2')
        .replace(/CO₂|CO2/g, 'se o dua').replace(/O₂/g, 'o dua')
        .replace(/Δ\s*/g, 'delta ').replace(/≤/g, ' maksimal ').replace(/≥/g, ' minimal ')
        .replace(/(^|[\s(])<\s*/g, '$1kurang dari ').replace(/(^|[\s(])>\s*/g, '$1lebih dari ').replace(/\s&\s/g, ' dan ')
        .replace(/[→⇄⟶]/g, ', ').replace(/[•|]/g, ', ').replace(/\s[-–—]\s/g, ', ')
        .replace(/(\s|\()\+(\d)/g, '$1plus $2').replace(/(\s|\()-(\d)/g, '$1minus $2')
        .replace(/(\d)\s*[-–]\s*(\d)/g, '$1 sampai $2')
        .replace(/(\d)\.(\d{1,2})(?!\d)/g, '$1,$2')
        .replace(/(\d+)\s*\/\s*(\d+)/g, '$1 per $2');
    ID_SPOKEN_UNITS.forEach(([re, rp]) => { t = t.replace(re, rp); });
    t = t.replace(/\b([A-Za-z]{2,6}s?)\b/g, (w) => (ID_SPOKEN_ACRONYMS[w] ? ID_SPOKEN_ACRONYMS[w] : w));
    return t.replace(/[()[\]"“”]/g, ' ').replace(/\s+/g, ' ').replace(/\s+,/g, ',').replace(/,(\s*,)+/g, ',').trim();
}
